const express = require('express');
const libxmljs = require('libxmljs');
const fs = require('fs');
const path = require('path');

const app = express();

// Middleware to parse raw XML bodies
app.use('/api/import', express.text({ type: 'application/xml', limit: '1mb' }));
app.use('/api/import', express.text({ type: 'text/xml', limit: '1mb' }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', uptime: process.uptime() });
});

// XML document import endpoint for invoice processing
app.post('/api/import/invoice', (req, res) => {
  try {
    const xmlBody = req.body;

    if (!xmlBody || typeof xmlBody !== 'string') {
      return res.status(400).json({ error: 'XML body required' });
    }

    // Parse XML with full feature set for DTD validation support
    const doc = libxmljs.parseXml(xmlBody, {
      dtdload: true,
      dtdvalid: false,
      noent: true,
      nocdata: false
    });

    // Extract invoice fields
    const invoiceId = doc.get('//invoice/id');
    const vendor = doc.get('//invoice/vendor');
    const amount = doc.get('//invoice/amount');
    const description = doc.get('//invoice/description');

    if (!invoiceId || !vendor || !amount) {
      return res.status(400).json({ error: 'Missing required invoice fields (id, vendor, amount)' });
    }

    const invoice = {
      id: invoiceId.text(),
      vendor: vendor.text(),
      amount: parseFloat(amount.text()),
      description: description ? description.text() : '',
      importedAt: new Date().toISOString()
    };

    // Validate amount
    if (isNaN(invoice.amount) || invoice.amount <= 0) {
      return res.status(400).json({ error: 'Invalid amount' });
    }

    // Log the import (in production this would go to a database)
    console.log(`Invoice imported: ${JSON.stringify(invoice)}`);

    return res.status(201).json({
      success: true,
      invoice: invoice
    });

  } catch (err) {
    console.error('XML parsing error:', err.message);
    return res.status(400).json({ error: 'Invalid XML document', details: err.message });
  }
});

// Batch import endpoint
app.post('/api/import/batch', (req, res) => {
  try {
    const xmlBody = req.body;
    const doc = libxmljs.parseXml(xmlBody, {
      dtdload: true,
      noent: true
    });

    const invoiceNodes = doc.find('//invoices/invoice');
    const results = invoiceNodes.map(node => {
      const id = node.get('id');
      const vendor = node.get('vendor');
      const amount = node.get('amount');
      return {
        id: id ? id.text() : 'unknown',
        vendor: vendor ? vendor.text() : 'unknown',
        amount: amount ? parseFloat(amount.text()) : 0
      };
    });

    return res.status(201).json({ success: true, count: results.length, invoices: results });
  } catch (err) {
    return res.status(400).json({ error: 'Batch import failed', details: err.message });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Invoice import service running on port ${PORT}`);
});
